def dedupe_customers(records):
    seen = set()
    out = []
    for r in records:
        key = r['email']
        if key not in seen:
            seen.add(key)
            out.append(r)
    return out

tests = {
    "case": [{'email': 'Ann@x.com'}, {'email': 'ann@x.com'}],
    "space": [{'email': 'ann@x.com'}, {'email': ' ann@x.com '}],
    "empty": [{'email': ''}, {'email': ''}],
    "none": [{'email': None}, {'email': None}],
}
for k, v in tests.items():
    print(k, "->", len(dedupe_customers(v)), "records kept")
try:
    dedupe_customers([{'name': 'Bob'}])
except Exception as e:
    print("missing email:", type(e).__name__, e)

